// Oeste Label — Topanga theme (v0.4.2).
// Copy-paste ready. Requires: React 18+ in scope, Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/src/index.js
// Docs: https://oeste.hiddeninwest.com/#/components/label

export function Label({ htmlFor, children, required = false }) {
  return (
    <label htmlFor={htmlFor} className="mb-2 block text-sm font-medium text-[#1c1917] dark:text-[#f5f3ef]">
      {children}
      {required && <span aria-hidden="true"> *</span>}
      {required && <span> <span className="text-[#706963] dark:text-[#9e968f]">(required)</span></span>}
    </label>
  );
}
